#!/usr/bin/env bash
# =============================================================================
# InstantGram v1.10.0  -  Chats, moments, search and views
#   * Clips: the volume slide changes the phone's real media volume.
#   * Views on every post and clip (shown on your profile grid and in the details sheet).
#   * Explore: search by title or #hashtag, trending tags, Posts | Clips | People, the grid
#     plays clips silently. Tap a #hashtag anywhere to search it. Tap a clip title for details.
#   * Chats: photos, GIFs (Giphy), voice messages, your location, shared posts, swipe to
#     reply, forward, reactions, delete (for me / for everyone), pin.
#   * Share button on posts and clips: send to people in the app, or share the link.
#   * Moments: add from your profile, photo or video, text, emoji stickers, music.
#   * Profile links have their own names. New brand font for "InstantGram".
#   * New Firestore rules (chat messages). Publish them after this update.
# Run from the project root:   bash update_v1100_chat_stories_search.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="f664949985a158993a9ea19519f621f5ab1bf809d49eb717061453dffee8bb38"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/widgets/brand_logo.dart ] || { echo "ERROR: v1.9.0 is not installed. Run update_v190_logo_login_audio.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')
echo "    Dart package: $APP_NAME"

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the updated files..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

echo "==> Adding the new packages and the brand font to pubspec.yaml..."
python3 - pubspec.yaml <<'PYX'
import re, sys
p = sys.argv[1] if len(sys.argv) > 1 else "pubspec.yaml"
s = open(p).read()
changed = []

def has_dep(name):
    return re.search(r"^[ \t]+" + re.escape(name) + r":", s, re.M) is not None

deps = [("volume_controller", "3.4.4"), ("record", "^6.2.1"), ("geolocator", "^14.0.2")]
m = re.search(r"^dependencies:[ \t]*\r?\n", s, re.M)
if not m:
    sys.exit("ERROR: no dependencies: section in pubspec.yaml")
add = ""
for name, ver in deps:
    if not has_dep(name):
        add += "  %s: %s\n" % (name, ver)
        changed.append(name)
if add:
    s = s[:m.end()] + add + s[m.end():]

if "family: Wordmark" not in s:
    block = ("  fonts:\n    - family: Wordmark\n      fonts:\n"
             "        - asset: assets/fonts/Pacifico-Regular.ttf\n")
    if re.search(r"^  fonts:[ \t]*$", s, re.M):
        s = re.sub(r"^  fonts:[ \t]*\r?\n", block, s, count=1, flags=re.M)
    else:
        m2 = re.search(r"^  uses-material-design:[ \t]*true[ \t]*\r?\n", s, re.M)
        if m2:
            s = s[:m2.end()] + "\n" + block + s[m2.end():]
        else:
            m3 = re.search(r"^flutter:[ \t]*\r?\n", s, re.M)
            if not m3:
                sys.exit("ERROR: no flutter: section in pubspec.yaml")
            s = s[:m3.end()] + block + s[m3.end():]
    changed.append("font Wordmark")

if changed:
    open(p, "w").write(s)
    print("    pubspec.yaml: added " + ", ".join(changed))
else:
    print("    pubspec.yaml: already up to date")
PYX

echo "==> Android: microphone and location permissions..."
python3 - <<'PYX'
import re
m = "android/app/src/main/AndroidManifest.xml"
try:
    t = open(m).read()
    perms = ["android.permission.RECORD_AUDIO",
             "android.permission.ACCESS_FINE_LOCATION",
             "android.permission.ACCESS_COARSE_LOCATION"]
    add = "".join('\n    <uses-permission android:name="%s"/>' % p for p in perms if p not in t)
    if add:
        t = re.sub(r"(<manifest[^>]*>)", lambda mo: mo.group(1) + add, t, count=1)
        open(m, "w").write(t)
        print("    AndroidManifest.xml: permissions added")
    else:
        print("    AndroidManifest.xml: permissions already there")
except FileNotFoundError:
    print("    WARNING: AndroidManifest.xml not found. Add RECORD_AUDIO, ACCESS_FINE_LOCATION and ACCESS_COARSE_LOCATION by hand.")
for g in ["android/app/build.gradle.kts", "android/app/build.gradle"]:
    try:
        s = open(g).read()
    except FileNotFoundError:
        continue
    n = s
    if g.endswith(".kts"):
        n = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = maxOf(flutter.minSdkVersion, 24)", n)
    else:
        n = re.sub(r"minSdk(Version)?(\s*=\s*|\s+)flutter\.minSdkVersion", lambda mo: "minSdk%s%sMath.max(flutter.minSdkVersion, 24)" % (mo.group(1) or "", mo.group(2)), n)
    if n != s:
        open(g, "w").write(n)
        print("    %s: minimum Android version set to 7.0 (needed by voice messages)" % g)
PYX

echo "==> Giphy key (for GIFs in chats)..."
KEY_FILE="lib/core/giphy_key.dart"
CURRENT=""
if [ -f "$KEY_FILE" ]; then
  CURRENT=$(sed -n "s/^const String kGiphyKey = '\(.*\)';.*/\1/p" "$KEY_FILE" | head -1)
fi
NEWKEY="${GIPHY_KEY:-}"
if [ -z "$NEWKEY" ] && [ -z "$CURRENT" ]; then
  echo "    Get a free key: https://developers.giphy.com -> Create an App -> API -> Create"
  echo "    Paste it here and press Enter (or just press Enter to do it later)."
  if ( : < /dev/tty ) 2>/dev/null; then read -r -p "    Giphy API key: " NEWKEY < /dev/tty || NEWKEY=""; fi
fi
if [ -n "$NEWKEY" ]; then
  bash tools/set_giphy_key.sh "$NEWKEY"
elif [ -n "$CURRENT" ]; then
  echo "    Keeping the Giphy key that is already saved."
else
  mkdir -p lib/core
  cat > "$KEY_FILE" <<'DART'
/// Your free Giphy API key (https://developers.giphy.com -> Create an App -> API).
/// Change it with:  bash tools/set_giphy_key.sh NEW_KEY   Leave it empty to hide GIFs.
const String kGiphyKey = '';
DART
  echo "    No key yet. GIFs stay off until you run:  bash tools/set_giphy_key.sh YOUR_KEY"
fi

echo ""
echo "Done. v1.10.0 is in place."
echo ""
echo "IMPORTANT: publish the new Firestore rules (chat photos, voice, reactions, pins need them)."
echo "  Firebase console -> Build -> Firestore Database -> Rules tab"
echo "  Select everything, delete it, paste the full contents of  firebase/firestore.rules , press Publish."
echo ""
echo "Next:"
echo "  flutter clean && flutter pub get && dart analyze && flutter test"
echo '  git add -A && git commit -m "v1.10.0: chats, moments, search, views" && git push'
exit 0
